"""Migrated Meridian CRM 4.2 ORD_HEADER discount validation rules."""

from decimal import Decimal, InvalidOperation


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value) -> Decimal:
    """Apply legacy numeric-context coercion, including empty string as zero."""
    if value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("pct must be a number or numeric string") from exc


def _lookup_role(user_id: str, users: list[dict]) -> str:
    """Return ROLE_ID from the first live matching USR_MASTER row."""
    for user in users:
        if user.get("USR_ID") == user_id and user.get("DEL_FLG", "") != "Y":
            return user.get("ROLE_ID", "")
    return ""


def set_discount(order: dict, pct, user_id: str, users: list[dict]) -> dict:
    """Validate and apply an ORD_HEADER discount without mutating inputs."""
    numeric_pct = _numeric_value(pct)

    # ORD-001: rule-file order.
    if not (Decimal("0") <= numeric_pct <= Decimal("100")):
        raise BusinessRuleViolation("E5001", "Discount out of range")

    # ORD-002: strictly greater than 20, using live-row LOOKUP semantics.
    if numeric_pct > Decimal("20"):
        role_id = _lookup_role(user_id, users)
        if role_id not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    updated_order = dict(order)
    updated_order["DISC_PCT"] = pct
    return updated_order
